    id: 17,
    slug: "kauen-nur-unter-aufsicht",
    title: "Kauartikel immer unter Aufsicht geben: Warum das kein Übertreiben ist",
    shortDescription:
      "Manche Kauartikel splittern oder werden im Ganzen verschluckt. Gib sie nur, wenn du den Hund beobachten kannst.",
    level: 1,
    tags: ["kauen", "sicherheit"],
    imageUrl: "/images/tipps/zaehne/17.jpg",
    imageAlt: "Hund kaut auf einem Artikel — Halter beobachtet ihn dabei",
    content: `„Ich geb ihm einfach den Knochen und kann in Ruhe kochen" — verständlich, aber riskant. Viele Kauartikelunfälle passieren genau dann, wenn niemand hinschaut. Ein kurzes Verschlucken, ein Splittern, ein Abbrechen — und ein Kauartikel wird zum Notfall.

## Warum Aufsicht wichtig ist

**Verschluckungsgefahr**: Viele Hunde, vor allem gierige Fresser, schlucken Kauartikel, wenn sie auf eine Größe geschrumpft sind, bei der sie gerade noch ins Maul passen. Ohne Aufsicht bemerkt du nicht, wann dieser Punkt erreicht ist.

**Splitternde Artikel**: Manche Kauartikel — vor allem Produkten auf Basis von Pflanzenfasern, Kollagen oder bestimmten gepressten Rohstoffen — können an Rändern absplittern. Diese Splitter können sich im Rachen oder Darm festsetzen.

**Intensive Powerkauer**: Hunde mit starkem Kauimpuls können auch robuste Artikel in Stücke reißen und diese schlucken. Bei solchen Hunden ist Aufsicht nochmal wichtiger.

## Wann du besonders aufpassen solltest

- Bei einem neuen Kauartikel zum ersten Mal
- Wenn der Artikel kleiner als handflächengroß geworden ist
- Bei Hunden, die dazu neigen, Dinge zu schlucken statt zu kauen
- Bei mehreren Hunden, die zusammen kauen — Konkurrenzdruck führt oft zu Hastigheit

## Wie du Aufsicht praktisch umsetzt

Aufsicht bedeutet nicht, dass du dich neben den Hund hocken und ihn anstarren musst. Es reicht:

- Im selben Raum sein und gelegentlich hinschauen
- Den Hund nicht allein in einem anderen Zimmer oder draußen mit dem Artikel lassen
- Artikel wegnehmen, wenn du das Haus verlässt oder nicht mehr aufpassen kannst

## Was im Notfall zu tun ist

Wenn du siehst, dass dein Hund einen großen Brocken schluckt:
- Ruhig bleiben, nicht in Panik geraten
- Beobachte, ob er würgt, Atemnot zeigt oder sich seltsam verhält
- Bei Würgen oder Atemnot: sofort zum Tierarzt oder Tierklinik
- Bei normalem Verhalten: Tierarzt anrufen und Lage schildern

## Häufige Fragen

### Kann ich meinen Hund kurz allein lassen, wenn der Kauartikel noch groß ist?
Kurz raus zum Briefkasten — vermutlich kein Problem. Längere Abwesenheit — lieber Artikel wegnehmen.

### Welche Kauartikel sind sicherer ohne Aufsicht?
Kauspielzeuge aus robusten Gummi-Materialien (keine lose Stücke) sind weniger riskant als Naturartikel. Aber sicherer als kein Artikel ist Aufsicht.

### Mein Hund kaut täglich ohne Probleme — muss ich wirklich aufpassen?
Ja. Kauunfälle sind selten, aber wenn sie passieren, sind sie oft ernst. Eine Minute Aufmerksamkeit kostet wenig.

## Das Wichtigste in Kürze

- Kauartikel können splittern, abbrechen oder zu klein und dann verschluckt werden.
- Aufsicht heißt: im selben Raum sein und gelegentlich hinsehen.
- Bei unbekannten Artikeln oder gierigen Fressern: immer dabei sein.
- Artikel wegnehmen, wenn du die Wohnung verlässt oder einschläfst.`,
