    title: "Wie oft Zähne putzen beim Hund? Das optimale Intervall",
    shortDescription:
      "Täglich, dreimal pro Woche, wöchentlich? Hier erfährst du, welches Putzintervall welchen Effekt hat — und was realistisch umsetzbar ist.",
