    id: 45,
    slug: "zahnpflege-diaet-hund",
    title: "Zahnpflege-Diät für Hunde: Wann lohnt sich Spezialfutter?",
    shortDescription:
      "Dental-Diäten versprechen saubere Zähne durch die richtige Textur. Hier erfährst du, für wen sie sich eignen und was du beachten musst.",
