    imageAlt: "Hund unter Aufsicht beim Kauen auf sicherem Kauartikel",
    content: `Kauartikel sind für viele Hunde eine Bereicherung — aber sie kommen mit echten Risiken, die viele Halter unterschätzen. Hier ist ein realistischer Blick auf Sicherheit im Umgang mit Kauartikeln.

## Die drei Hauptrisiken

### 1. Erstickung und Atemwegsblockade
Das gefährlichste unmittelbare Risiko. Entsteht, wenn:
- Ein Kauartikel so weit abgekaut wird, dass ein zu kleines Stück abgetrennt und geschluckt werden kann
- Die Größe des Artikels nicht der Hundegröße entspricht
- Weiche Artikel in einem Stück runtergeschluckt werden

**Maßnahme:** Immer beaufsichtigen. Wenn der Artikel kleiner als die Hundeschnauze geworden ist, wegnehmen.

### 2. Gastrointestinale Perforation
Scharfe Splitter (besonders von Knochen und hartem Naturmaterial) können Speiseröhre, Magen oder Darm verletzen. Symptome: Erbrechen, Blut im Stuhl, Lethargie, Bauchschmerzen.

**Maßnahme:** Hart abbrechende Materialien (Geweih, harte Knochen, Nylonknochen) vermeiden. Bei Symptomen sofort zum Tierarzt.

### 3. Zahnfrakturen
Zu hartes Material überfordert die Zähne, besonders die Prämolaren. Zahnfrakturen sind schmerzhaft, teuer zu behandeln und können infektiöse Komplikationen haben.

**Maßnahme:** Fingernagel-Regel anwenden. Weicheres Material bevorzugen.

## Die Fingernagel-Regel (Erinnerung)

Drück deinen Fingernagel in das Material. Hinterlässt er keine Delle: zu hart.

Geweih, Kuhhufe, Nylonknochen, rohe Rinderknochen ohne Fleisch — alle scheitern an dieser Regel.

## Sicherheitscheckliste vor jedem Kauartikel

✓ **Richtige Größe?** Artikel größer als der breiteste Teil der Hundemündung.
✓ **Richtige Härte?** Fingernagel-Test bestanden.
✓ **Beaufsichtigt?** Niemals unbeobachtet.
✓ **Frisch genug?** Kein schimmeliges oder übelriechendes Material.
✓ **Keine Resthärte?** Bei sehr weichen Artikeln besteht Schluckrisiko im ganzen Stück.

## Materialklassifizierung

| Sicherheit | Materialien |
|---|---|
| Hoch | Ochsenziemer, Büffelhaut, Knorpel, Hühnerknochen (roh, beaufsichtigt) |
| Mittel | Gepresste Kaurollen, VOHC-Dental Chews, Kaustreifen |
| Niedrig | Geweih, Kuhhufe, Nylonknochen, harte Pressknochen |
| Kochen | Alle gekochten Knochen (immer verboten — werden brüchig) |

## Was tun im Notfall

**Bei Erstickung:** Hund auf die Seite, Maul vorsichtig öffnen, sichtbares Objekt entfernen (nur wenn sicher erreichbar). Sofort tierärztliche Notaufnahme.

**Bei Schlucken von Knochenstücken:** Nicht abwarten. Sofort zum Tierarzt. Symptome können bis zu 48 Stunden nach dem Ereignis auftreten.

## Häufige Fragen

### Kann ich meinen Hund kurz allein mit einem Kauartikel lassen?
Für ausgewiesene Sicherheitsprodukte (VOHC Dental Chews) mit richtiger Größe: kurz ja. Für Naturmaterial wie Knochen oder Geweih: nein.

### Ab wann ist ein Kauartikel zu abgenutzt?
Wenn einzelne größere Stücke abzubrechen beginnen oder der Rest kleiner als zwei Fingerbreiten ist.

### Sind Hunde-Kauspielzeug (Kong, etc.) sicherer?
Ja. Synthetische Kauartikel aus geprüften Materialien mit entsprechender Kennzeichnung sind für unbeaufsichtigtes Spielen besser geeignet als Naturmaterial.

## Fazit

Kauartikel sind wertvoll — aber nicht ohne Risiken. Richtige Größe, geeignete Härte und Aufsicht sind die drei Regeln, die die meisten Unfälle verhindern.`,
