    title: "Parodontitis beim Hund erkennen: Lockere Zähne, Bluten, Gestank",
    shortDescription:
      "Lockere Zähne, Zahnfleischbluten und starker Mundgeruch sind Warnzeichen einer fortgeschrittenen Parodontitis — nicht abwarten.",
