    tags: ["zahnstein", "komplikationen"],
    imageUrl: "/images/tipps/zaehne/8.jpg",
    imageAlt: "Stark zahnsteinbedeckter Hundezahn — sichtbare Komplikationen",
    content: `Wenn Tierärzte von Zahnstein beim Hund reden, meinen sie meist nicht nur den gelblich-braunen Belag, der unschön aussieht. Sie meinen den Ausgangspunkt einer Kaskade, die von der Mundhöhle bis in die inneren Organe reichen kann. Wer das versteht, putzt anders.

## Schritt 1: Plaque entsteht

Innerhalb von Stunden nach dem Fressen bilden Bakterien auf der Zahnoberfläche eine klebrige Schicht — die Plaque. Sie ist zunächst weich und lässt sich durch Bürsten oder Kauen entfernen.

## Schritt 2: Zahnstein mineralisiert

Innerhalb weniger Tage verkalkt die Plaque durch Mineralien im Speichel und wird zum harten Zahnstein. Was einmal Zahnstein ist, lässt sich nicht mehr wegputzen — nur professionell entfernen.

## Schritt 3: Zahnfleischentzündung (Gingivitis)

Der Zahnstein liegt direkt am Zahnfleischrand und reizt das Gewebe dauerhaft. Das Zahnfleisch rötet sich, schwillt an und blutet leicht. Gingivitis ist noch reversibel — wenn rechtzeitig gehandelt wird.

## Schritt 4: Parodontitis

Unbehandelt wandert die Entzündung in die Tiefe. Das Bindegewebe zwischen Zahn und Knochen wird zerstört, Taschen entstehen zwischen Zahn und Zahnfleisch, Bakterien siedeln sich darin an. Der Knochen baut sich ab. Zähne lockern sich und fallen schließlich aus.

## Schritt 5: Bakteriämie und Organschäden

Das ist der gefürchtetste Schritt: Bakterien aus dem entzündeten Zahnfleisch gelangen ins Blut und erreichen die Organe:

- **Herz:** Bakterien können sich an den Herzklappen absetzen und zu Endokarditis führen.
- **Nieren:** Chronische Bakterienbelastung kann Nierengewebe schädigen.
- **Leber:** Ähnliche Mechanismen wie bei den Nieren, jedoch weniger häufig dokumentiert.

Diese Zusammenhänge sind bei Menschen gut belegt und werden beim Hund zunehmend anerkannt.

## Was das für die Pflege bedeutet

Zahnpflege ist nicht nur Ästhetik. Sie unterbricht die Kaskade an Punkt 1 — bevor Plaque zu Zahnstein wird. Täglich putzen, regelmäßig Kauen, halbjährlich kontrollieren.

## Häufige Fragen

### Reicht eine Zahnreinigung alle paar Jahre?
Nein. Die Reinigung entfernt existierenden Zahnstein. Ohne tägliche Vorbeugung bildet er sich rasch neu.

### Ab wann ist Zahnstein gefährlich?
Schon mittelgradiger Zahnstein reizt das Zahnfleisch dauerhaft. Je früher du eingreifst, desto günstiger der Verlauf.

## Das Wichtigste in Kürze

- Zahnstein ist nicht nur Optik — er startet eine Entzündungskaskade.
- Gingivitis ist noch reversibel, Parodontitis nicht vollständig.
- Bakterien aus kranken Zähnen können Herz, Nieren und Leber schädigen.
- Tägliche Pflege unterbricht die Kette, bevor Schäden entstehen.`,
