    id: 67,
    slug: "zahn-roentgen-hund",
    title: "Zahn-Röntgen beim Hund: Warum es unverzichtbar ist",
    shortDescription:
      "Was über der Zahnfleischlinie sichtbar ist, zeigt nur die halbe Wahrheit. Röntgen macht Wurzeln, Knochen und versteckte Erkrankungen sichtbar.",
    level: 2,
    tags: ["roentgen", "diagnose"],
    imageUrl: "/images/tipps/zaehne/1.jpg",
    imageAlt: "Zahnröntgenaufnahme eines Hundes — Knochen und Wurzeln sichtbar",
    content: `Der Zahn, der von außen ordentlich aussieht, kann innen längst abgestorben sein. Das Zahnfleisch, das sauber wirkt, kann tief darunter einen Abszess verbergen. Ohne Röntgen bleibt die Hälfte der Zahngesundheit unsichtbar.

## Was Röntgen sichtbar macht

Das menschliche Auge sieht beim Hund nur, was über oder knapp unter dem Zahnfleischrand liegt. Röntgen zeigt:

- **Den Alveolarknochen** — wie viel Knochen um die Wurzel noch vorhanden ist
- **Die Zahnwurzeln** — ihre Länge, Form, Stellung und ob sie intakt sind
- **Periapikale Veränderungen** — Entzündungen an der Wurzelspitze, die außen nicht sichtbar sind
- **Zahnfrakturen** — auch solche, die unter dem Zahnfleisch liegen
- **Resorptionen** — wenn Zahn- oder Knochensubstanz sich von innen oder außen auflöst
- **Persistierende Milchzahnwurzeln** — auch wenn die Krone weg ist
- **Überzählige Zähne** im Knochen, die nicht durchgebrochen sind

## Wann Röntgen bei der Zahnreinigung nötig ist

Die American Veterinary Dental College empfiehlt Röntgenaufnahmen bei jeder professionellen Reinigung — zumindest bei auffälligen Befunden. In vielen deutschen Praxen ist Röntgen bei der Zahnreinigung noch nicht Routine, wird aber zunehmend Standard, besonders bei:

- Sichtbaren Zahnfrakturen
- Verdacht auf Abszess (Gesichtsschwellung, Fistel)
- Unklarer Lockerheit von Zähnen
- Persistierenden Milchzähnen
- Extraktionsentscheidungen — damit man weiß, was einen erwartet

## Wie viele Bilder nötig sind

Ein vollständiger Zahnstatus beim Hund besteht aus mehreren Einzelaufnahmen — oft 8 bis 12 Bilder für alle Quadranten. Das ist aufwendiger als beim Menschen, weil die Zahnmorphologie anders ist und jede Wurzel einzeln dargestellt werden muss.

## Solltest du auf Röntgen bestehen?

Wenn dein Hund eine professionelle Zahnreinigung bekommt, frag aktiv nach, ob Röntgen angeboten wird und empfohlen wird. Bei Verdacht auf Zahnerkrankung ist es kein Luxus — es ist die Basis für gute Entscheidungen. Extraktion ohne Röntgen kann bedeuten, dass Wurzelreste zurückbleiben.

## Das Wichtigste in Kürze

- Röntgen macht Wurzeln, Knochen und versteckte Erkrankungen sichtbar.
- Was außen gesund aussieht, kann innen krank sein — ohne Röntgen unsichtbar.
- Bei Verdacht auf Abszess, Fraktur, lockere Zähne: Röntgen ist nötig.
- Frag bei der Zahnreinigung aktiv nach, ob Röntgen empfohlen wird.`,
