    content: `Zahnprobleme sind bei Hunden insgesamt häufig — aber unter den kleinen Rassen besonders verbreitet. Chihuahua, Yorkshire Terrier, Maltese, Dachshund, Pomeranian, Toy-Pudel: Sie alle haben eine überproportional hohe Rate an Zahnstein, Parodontitis und frühem Zahnverlust.

## Warum kleine Rassen stärker betroffen sind

### Zähne auf engem Raum
Kleine Hunde haben im Verhältnis zur Kiefergröße große Zähne — ähnlich wie bei brachycephalen Rassen, nur etwas weniger extrem. Engstand fördert Plaqueanlagerung.

### Genetische Prädisposition
Einige kleine Rassen haben genetisch eine Neigung zu besonders hartem Speichel (hoher Mineralgehalt), was die Mineralisierung von Plaque zu Zahnstein beschleunigt.

### Seltener intensive Kaukontakte
Große Hunde kauen naturgemäß an größeren Dingen, was mechanisch mehr Plaque entfernt. Kleine Hunde bekommen oft kleinere, weichere Kauartikel — das mechanische Reinigungspotenzial ist geringer.

### Geringere Maulöffnung
Kleine Schnauzen sind für den Halter schwerer zugänglich und werden daher auch seltener gründlich untersucht. Probleme fallen später auf.

## Typische Befunde bei kleinen Rassen

- **Zahnstein bereits in jungen Jahren** — oft schon mit 1–2 Jahren
- **Frühzeitige Parodontitis** — Knochenverlust und lockere Zähne
- **Zahnverlust im mittleren Alter** — wenn Prävention ausgeblieben ist
- **Persistierende Milchzähne** — besonders häufig bei Toy-Rassen

## Was bei kleinen Rassen pflegerisch wichtig ist

**Frühzeitig beginnen:** Mit der Zahnpflege schon beim Welpen anfangen — kleine Rassen entwickeln Probleme früh.

**Täglich putzen:** Keine Kompromisse. Die Veranlagung erfordert konsequente Routine.

**Kleines, feines Werkzeug:** Fingerlinge oder kleine Hundezahnbürsten, die gut in den kleinen Kiefer passen.

**Halbjährliche Kontrolle:** Nicht auf jährlich verlassen — halbjährlich ist bei kleinen Rassen Standard.

**Geeignete Kauartikel:** Nicht zu weich (kein Reinigungseffekt), nicht zu hart (Zahnbruch). Maßstab: Kauartikel mit etwas Eigenelastizität.

## Das Wichtigste in Kürze

- Kleine Rassen haben überproportional häufig Zahnprobleme.
- Engstand, genetische Veranlagung und geringerer Kaueffekt sind die Hauptursachen.
- Früh beginnen, täglich putzen, halbjährlich kontrollieren.
- Zahnprobleme bei kleinen Hunden nicht als „normal" hinnehmen.`,
