    keywords: ["Zahngesundheit Hund Lebensqualität", "Hund Zahnschmerz erkennen", "Hund Wohlbefinden Zähne", "gesunde Zähne Hund", "Hund Zahnpflege Fürsorge"],
    geoRelevant: false,
